package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.widget.*;import android.database.*;import com.irwi.fincapp.repository.AnimalRepository;import com.irwi.fincapp.session.SessionManager;import com.irwi.fincapp.sync.SyncScheduler;
public class AnimalActivity extends Activity{AnimalRepository repo;LinearLayout list;String type; public void onCreate(Bundle b){super.onCreate(b);repo=new AnimalRepository(this);type=getIntent().getStringExtra("type");if(type==null)type="Cattle";LinearLayout l=BaseUi.root(this);l.addView(BaseUi.title(this,"Manage "+type));EditText tag=BaseUi.input(this,"Identification tag");EditText birth=BaseUi.input(this,"Birth date YYYY-MM-DD");Button save=BaseUi.btn(this,"Save animal offline");l.addView(tag);l.addView(birth);l.addView(save);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);l.addView(BaseUi.text(this,"Offline animals",22));l.addView(list);save.setOnClickListener(v->{String t=tag.getText().toString().trim();if(t.isEmpty()){BaseUi.toast(this,"Identification tag is required");return;}repo.addAnimal(new SessionManager(this).farmId(),type,t,birth.getText().toString().trim());tag.setText("");birth.setText("");SyncScheduler.schedule(this);render();BaseUi.toast(this,"Animal saved offline: pending sync");});render();}
 void render(){list.removeAllViews();Cursor c=repo.animals();try{while(c.moveToNext()){long id=c.getLong(0);String tag=c.getString(1), tp=c.getString(2), st=c.getString(3);Button b=BaseUi.btn(this,"#"+id+"  "+tag+" • "+tp+" • "+st+"\nTap to add weight / health");list.addView(b);b.setOnClickListener(v->showLogDialog(id,tag));}}finally{c.close();}}
 void showLogDialog(long id,String tag){final String[] options={"Append weight","Log health symptoms"};new AlertDialog.Builder(this).setTitle(tag).setItems(options,(d,which)->{if(which==0)weight(id);else health(id);}).show();}
 void weight(long id){EditText e=BaseUi.input(this,"Weight kg");new AlertDialog.Builder(this).setTitle("Append weight").setView(e).setPositiveButton("Save",(d,w)->{try{repo.addWeight(id,Double.parseDouble(e.getText().toString()));SyncScheduler.schedule(this);BaseUi.toast(this,"Weight saved offline");}catch(Exception ex){BaseUi.toast(this,"Invalid weight");}}).setNegativeButton("Cancel",null).show();}
 void health(long id){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText symptoms=BaseUi.input(this,"Symptoms description");EditText diag=BaseUi.input(this,"Diagnosis");EditText treat=BaseUi.input(this,"Treatment administered");l.addView(symptoms);l.addView(diag);l.addView(treat);new AlertDialog.Builder(this).setTitle("Health record").setView(l).setPositiveButton("Save",(d,w)->{repo.addHealth(id,symptoms.getText().toString(),diag.getText().toString(),treat.getText().toString());SyncScheduler.schedule(this);BaseUi.toast(this,"Health record saved offline");}).setNegativeButton("Cancel",null).show();}
}
